-- Milestone 9: campaign builder + publishing
CREATE TABLE "CampaignPlan" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "adAccountId" TEXT NOT NULL, "name" TEXT NOT NULL, "objective" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'draft', "externalCampaignId" TEXT, "metaStatus" TEXT, "createdById" TEXT NOT NULL, "approvedById" TEXT, "approvedAt" TIMESTAMP(3), "rejectionReason" TEXT, "publishedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CampaignPlan_pkey" PRIMARY KEY ("id"));
CREATE INDEX "CampaignPlan_organizationId_status_idx" ON "CampaignPlan"("organizationId","status");
CREATE TABLE "CampaignAdSet" ("id" TEXT NOT NULL, "planId" TEXT NOT NULL, "name" TEXT NOT NULL, "externalAdSetId" TEXT, "dailyBudgetMinor" BIGINT, "lifetimeBudgetMinor" BIGINT, "billingEvent" TEXT NOT NULL DEFAULT 'IMPRESSIONS', "optimizationGoal" TEXT NOT NULL, "pageId" TEXT, "pixelId" TEXT, "targeting" JSONB NOT NULL, "startTime" TIMESTAMP(3), "endTime" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CampaignAdSet_pkey" PRIMARY KEY ("id"));
CREATE INDEX "CampaignAdSet_planId_idx" ON "CampaignAdSet"("planId");
CREATE TABLE "CampaignAd" ("id" TEXT NOT NULL, "adSetId" TEXT NOT NULL, "name" TEXT NOT NULL, "externalAdId" TEXT, "productId" TEXT, "primaryText" TEXT NOT NULL, "headline" TEXT, "description" TEXT, "linkUrl" TEXT NOT NULL, "callToAction" TEXT NOT NULL DEFAULT 'SHOP_NOW', "imageUrl" TEXT, "createdByAi" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CampaignAd_pkey" PRIMARY KEY ("id"));
CREATE INDEX "CampaignAd_adSetId_idx" ON "CampaignAd"("adSetId");
CREATE TABLE "CampaignPublishLog" ("id" TEXT NOT NULL, "planId" TEXT NOT NULL, "actorId" TEXT, "step" TEXT NOT NULL, "entityRef" TEXT, "externalId" TEXT, "status" TEXT NOT NULL, "error" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CampaignPublishLog_pkey" PRIMARY KEY ("id"));
CREATE INDEX "CampaignPublishLog_planId_createdAt_idx" ON "CampaignPublishLog"("planId","createdAt");
ALTER TABLE "CampaignPlan" ADD CONSTRAINT "CampaignPlan_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CampaignAdSet" ADD CONSTRAINT "CampaignAdSet_planId_fkey" FOREIGN KEY ("planId") REFERENCES "CampaignPlan"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CampaignAd" ADD CONSTRAINT "CampaignAd_adSetId_fkey" FOREIGN KEY ("adSetId") REFERENCES "CampaignAdSet"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CampaignPublishLog" ADD CONSTRAINT "CampaignPublishLog_planId_fkey" FOREIGN KEY ("planId") REFERENCES "CampaignPlan"("id") ON DELETE CASCADE ON UPDATE CASCADE;
